import{test,before,after}from'node:test';import assert from'node:assert/strict';import{createServer}from'node:http';import{readFileSync,existsSync,statSync,mkdirSync}from'node:fs';import path from'node:path';import{chromium}from'playwright';
const site=path.resolve(import.meta.dirname,'../COPY_TO_GITHUB');let server,browser,origin;
const preview=JSON.parse(readFileSync(path.join(site,'js/local-preview-data.js'),'utf8').match(/window.BAG_DAY_LOCAL_FILES=(\{.*\});/)[1]);
before(async()=>{server=createServer((req,res)=>{const url=new URL(req.url,'http://local');let file=path.resolve(site,'.'+decodeURIComponent(url.pathname));if(!file.startsWith(site+path.sep)&&file!==site){res.writeHead(403).end();return}if(existsSync(file)&&statSync(file).isDirectory())file=path.join(file,'index.html');const relative=path.relative(site,file);if(relative==='analytics_config.txt'){res.end('Analytics_Enabled=true\nMeasurement_ID=G-TEST123456\n');return}if(preview[relative]!==undefined&&!existsSync(file)){res.end(preview[relative]);return}try{res.setHeader('Content-Type',({'.html':'text/html','.mjs':'text/javascript','.js':'text/javascript','.css':'text/css','.json':'application/json','.png':'image/png','.svg':'image/svg+xml'})[path.extname(file)]||'application/octet-stream');res.end(readFileSync(file))}catch{res.writeHead(404).end()}});await new Promise(r=>server.listen(0,'127.0.0.1',r));origin='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({headless:true,...(process.env.CHROMIUM_PATH?{executablePath:process.env.CHROMIUM_PATH}:{}),args:['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-zygote',...JSON.parse(process.env.CHROMIUM_EXTRA_ARGS||'[]')]})});
after(async()=>{await browser?.close();await new Promise(r=>server.close(r))});
const future=new Date(Date.now()+20*86400000).toISOString(),localities=[{locality_id:'Z',name:'Żejtun'},{locality_id:'K',name:'Kalkara'}];
async function setup({consent='granted',excluded=false,signed=false,enrolled=true,tagBlocked=false,tagDelay=0,width=1280,height=960,extraItems=0,sponsorCount=1,sponsorImages=false}={}){
 const context=await browser.newContext({viewport:{width,height},serviceWorkers:'block',reducedMotion:'reduce',geolocation:{latitude:35.855,longitude:14.533},permissions:['geolocation']});
 await context.addInitScript(({consent,excluded})=>{try{if(localStorage.getItem('fixture-initialised'))return;localStorage.setItem('fixture-initialised','true');if(consent)localStorage.setItem('bag-day-analytics-consent-v1',consent);localStorage.setItem('bag-day-analytics-exclude-v1',String(excluded));localStorage.setItem('bag-day-locality-v1','Żejtun');localStorage.setItem('bag-day-welcome-complete-v1','true');localStorage.setItem('bag-day-open-count-v1','3');localStorage.setItem('bag-day-follow-location-v1','false')}catch{}},{consent,excluded});
 let googleRequests=0,failCreate=false,replayed=false,alreadyEnrolled=false;
 const errors=[],requests=[],page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));
 await context.route('https://www.googletagmanager.com/**',async r=>{googleRequests++;if(tagBlocked)return r.abort();if(tagDelay)await new Promise(r=>setTimeout(r,tagDelay));await r.fulfill({contentType:'text/javascript',body:"window.__gaCommands=(window.dataLayer||[]).map(x=>Array.from(x));const old=window.dataLayer.push.bind(window.dataLayer);window.dataLayer.push=function(x){window.__gaCommands.push(Array.from(x));return old(x)};"})});
 await context.route('https://**.google-analytics.com/**',r=>r.abort());
 await context.route('https://nominatim.openstreetmap.org/**',r=>r.fulfill({json:{address:{town:'Żejtun',country:'Malta'}}}));
 await context.route('https://accounts.google.com/gsi/client',r=>r.fulfill({contentType:'text/javascript',body:"window.google={accounts:{id:{initialize(o){window.testGoogle=o.callback},renderButton(el){const b=document.createElement('button');b.textContent='Continue with Google';b.onclick=()=>window.testGoogle({credential:'PRIVATE_TOKEN'});el.append(b)}}}}"}));
 const me={user:{display_name:'PRIVATE_NAME',email:'PRIVATE_EMAIL@example.test'},contributor:enrolled?{status:'APPROVED',trust_level:'TRUSTED',display_name:'PRIVATE_NAME',locality_id:'Z',contact_phone:'+35699123456'}:null,listing_limit:3,trusted_autopublish:false,items:[]};
 const publicItems=[{item_id:'PRIVATE_ITEM_ID',description:'PRIVATE_DESCRIPTION',owner_name:'PRIVATE_OWNER',locality_id:'Z',locality_name:'Żejtun',contact_mode:'PHONE',has_phone:1,external_url:'https://example.test/PRIVATE_ADVERT',submitted_at:new Date(Date.now()-2*86400000).toISOString(),delete_at:future},{item_id:'two',description:'Pots',owner_name:'Alex',locality_id:'K',locality_name:'Kalkara',contact_mode:'LINK',has_phone:0,external_url:'https://example.test/pots',submitted_at:new Date(Date.now()-5*86400000).toISOString(),delete_at:future}];
 for(let i=0;i<extraItems;i++)publicItems.push({...publicItems[0],item_id:'row-'+i,description:'Free household item '+(i+1)+' in good condition',submitted_at:new Date(Date.now()-(i+3)*86400000).toISOString(),external_url:null});
 await context.route('https://api.bagdaymalta.eu/**',async r=>{const u=new URL(r.request().url()),p=u.pathname.replace('/api/v1',''),method=r.request().method(),body=['POST','PATCH'].includes(method)?r.request().postDataJSON():null;requests.push({p,method,body});const send=(json,status=200)=>r.fulfill({status,json,headers:{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Credentials':'true','Access-Control-Allow-Headers':'content-type','Access-Control-Allow-Methods':'GET,POST,PATCH,OPTIONS'}});if(method==='OPTIONS')return send({});
 if(p==='/reuse/me')return signed?send(me):send({error:{message:'Sign in'}},401);
 if(p==='/public/reuse/localities')return send({items:localities});if(p==='/public/reuse/items')return send({items:publicItems.filter(i=>!u.searchParams.get('locality_id')||i.locality_id===u.searchParams.get('locality_id')).slice(Number(u.searchParams.get('offset')||0),Number(u.searchParams.get('offset')||0)+Number(u.searchParams.get('limit')||20))});
 if(p==='/auth/public/config')return send({google_client_id:'test.apps.googleusercontent.com',nonce:'PRIVATE_NONCE'});if(p==='/auth/public/google'){signed=true;return send({ok:true})}if(p==='/auth/public/logout'){signed=false;return send({signed_out:true})}
 if(p.endsWith('/contact'))return send({contact_phone:'+35699123456'});
 if(p==='/reuse/enrolment'){me.contributor={status:'PENDING',display_name:body.display_name};return send({status:'PENDING',already_submitted:alreadyEnrolled},201)}
 if(p==='/reuse/items'||p.startsWith('/reuse/items/')){if(failCreate)return send({error:{message:'PRIVATE_ERROR'}},500);const item={...body,item_id:body.item_id||p.split('/').pop(),status:body.action==='TAKEN'?'TAKEN':body.action==='WITHDRAW'?'WITHDRAWN':'PENDING',revision:2,submitted_at:me.items[0]?.submitted_at||new Date().toISOString(),delete_at:future,contact_mode:body.contact_phone?'PHONE':'LINK'};me.items=[item];return send({item,replayed},method==='POST'?201:200)}return send({},404);
 });
 const date=new Date(),version='fixture-publication';await context.route('https://bagday-sponsor-export.davvel.workers.dev/**',r=>{const p=new URL(r.request().url()).pathname;const sponsors=Array.from({length:sponsorCount},(_,i)=>(i?'TEST-SPONSOR-'+i:'TEST-SPONSOR')+',Test shop '+i+',Useful things '+i+','+(sponsorImages?origin+'/images/sponsors/google.png':'')+',https://example.test/shop').join('\n');const slots=Array.from({length:sponsorCount},(_,i)=>(date.getUTCMonth()+1)+','+date.getUTCFullYear()+',Żejtun,'+(i+1)+','+(i?'TEST-SPONSOR-'+i:'TEST-SPONSOR')).join('\n');return p==='/current.json'?r.fulfill({json:{format_version:1,version,sponsor_count:sponsorCount,slot_count:sponsorCount,sponsors_url:'/exports/'+version+'/sponsors.csv',sponsor_slots_url:'/exports/'+version+'/sponsor_slots.csv'}}):r.fulfill({body:p.endsWith('/sponsor_slots.csv')?'Month,Year,Locality,Slot,SponsorID\n'+slots+'\n':'SponsorID,SponsorName,DisplayText,ImageURL,URL\n'+sponsors+'\n'})});
 await page.addInitScript(()=>document.addEventListener('click',e=>{if(e.target.closest('a'))e.preventDefault()}));
 return{context,page,errors,requests,fixtureMe:me,publicItems,googleRequests:()=>googleRequests,setFail:v=>failCreate=v,setReplayed:v=>replayed=v,setAlreadyEnrolled:v=>alreadyEnrolled=v,events:async(name)=>page.evaluate(n=>(window.__gaCommands||[]).filter(c=>c[0]==='event'&&(!n||c[1]===n)).map(c=>({name:c[1],params:c[2]})),name),ready:()=>page.waitForFunction(()=>window.BAG_DAY_ANALYTICS?.status().ready),close:()=>context.close()};
}
async function editIcons(s){if(await s.page.locator('#editIcon').isVisible())await s.page.locator('#editIcon').click()}
async function openManualIcons(s){await editIcons(s);if(!await s.page.locator('#emojiChoices').evaluate(el=>el.open))await s.page.locator('#manualIcons').click()}
async function togglePalette(s){if(await s.page.locator('#emojiChoices summary').isVisible())await s.page.locator('#emojiChoices summary').click()}
async function reuse(s){await s.page.goto(origin+'/reuse/',{waitUntil:'domcontentloaded'});await s.page.locator('#allLocalities').waitFor()}
async function home(s){await s.page.goto(origin+'/');await s.page.locator('#dashboard:not([hidden])').waitFor()}
async function count(s,name,n){await s.page.waitForFunction(({name,n})=>(window.__gaCommands||[]).filter(c=>c[0]==='event'&&c[1]===name).length===n,{name,n})}
function privateFree(events){assert.doesNotMatch(JSON.stringify(events),/PRIVATE_|99123456|example\.test|contact_phone|user_id|item_id|why_reuse|credential/)}
test('direct REUSE asks non-blocking consent; no retroactive events, no tag before consent, immediate withdrawal',async()=>{const s=await setup({consent:null});try{await reuse(s);assert.equal(s.googleRequests(),0);assert.equal(await s.page.locator('#usageConsent').isVisible(),true);await s.page.locator('#feed .item-row').first().waitFor();await s.page.locator('#usageConsent [data-allow]').click();await s.ready();await count(s,'page_view',1);assert.equal((await s.events('reuse_search')).length,0);await s.page.locator('#allLocalities').uncheck();await count(s,'reuse_filter_changed',1);await count(s,'reuse_search',1);await s.page.evaluate(()=>document.cookie='_ga=fixture; path=/');assert.equal(await s.page.locator('#analyticsPreferences').count(),0);const settingsPage=await s.context.newPage();await settingsPage.goto(origin+'/');await settingsPage.locator('#dashboard:not([hidden])').waitFor();await settingsPage.locator('#settingsButton').click();await settingsPage.locator('#allowAnalytics').uncheck();await s.page.waitForFunction(()=>window.BAG_DAY_ANALYTICS.status().consent==='denied');await settingsPage.close();const before=(await s.events()).length;await s.page.locator('#allLocalities').check();await s.page.waitForTimeout(100);assert.equal((await s.events()).length,before);assert.equal(await s.page.evaluate(()=>document.cookie.includes('_ga=')),false);assert.equal(await s.page.evaluate(()=>window['ga-disable-G-TEST123456']),true);assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('denied consent and excluded test devices remain functional without Google',async()=>{for(const options of[{consent:'denied'},{excluded:true}]){const s=await setup(options);try{await reuse(s);await s.page.locator('#allLocalities').check();assert.equal(s.googleRequests(),0);assert.equal((await s.events()).length,0);assert.equal(await s.page.locator('#usageConsent').isVisible(),false);assert.deepEqual(s.errors,[])}finally{await s.close()}}});
test('one tag and pageview per document, safe URL fields, daily-use dedup across Home and REUSE',async()=>{const s=await setup();try{await s.page.goto(origin+'/?email=PRIVATE_EMAIL#PRIVATE_HASH');await s.ready();await count(s,'page_view',1);const events=await s.events();assert.equal(events.find(e=>e.name==='page_view').params.page_location,origin+'/');privateFree(events);assert.equal((await s.events('bagday_daily_use')).length,1);await s.page.evaluate(()=>{const a=document.createElement('script');a.src='/js/analytics.js';document.body.append(a)});await s.page.waitForTimeout(100);assert.equal(s.googleRequests(),1);await count(s,'page_view',1);await reuse(s);await s.ready();await count(s,'page_view',1);assert.equal((await s.events('bagday_daily_use')).length,0);assert.equal((await s.events('reuse_open')).length,1)}finally{await s.close()}});
test('consented events queue during tag loading once; unapproved parameters and unknown events are discarded',async()=>{const s=await setup({tagDelay:500});try{await reuse(s);await s.page.evaluate(()=>{window.BAG_DAY_ANALYTICS.event('reuse_give_click',{entry_point:'give_button',email:'PRIVATE_EMAIL',contact_phone:'+35699123456',external_url:'PRIVATE_ADVERT',description:'PRIVATE_DESCRIPTION'});window.BAG_DAY_ANALYTICS.event('unknown_event',{email:'PRIVATE_EMAIL'})});await s.ready();await count(s,'reuse_give_click',1);privateFree(await s.events());assert.equal((await s.events('unknown_event')).length,0)}finally{await s.close()}});
test('withdrawal during loading discards queued actions and emits no retroactive pageviews',async()=>{const s=await setup({tagDelay:700});try{await reuse(s);await s.page.evaluate(()=>{window.BAG_DAY_ANALYTICS.event('reuse_give_click',{entry_point:'give_button'});window.BAG_DAY_ANALYTICS.setConsent(false)});await s.page.waitForTimeout(850);assert.equal((await s.events()).length,0);await s.page.evaluate(()=>window.BAG_DAY_ANALYTICS.setConsent(true));await s.ready();await count(s,'page_view',1);assert.equal((await s.events('reuse_give_click')).length,0);assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('cross-tab withdrawal stops existing pages and regrant does not duplicate pageviews',async()=>{const s=await setup();try{await reuse(s);await s.ready();const other=await s.context.newPage();await other.goto(origin+'/reuse/');await other.waitForFunction(()=>window.BAG_DAY_ANALYTICS?.status().ready);await other.evaluate(()=>window.BAG_DAY_ANALYTICS.setConsent(false));await s.page.waitForFunction(()=>window.BAG_DAY_ANALYTICS.status().consent==='denied');const n=(await s.events()).length;await s.page.evaluate(()=>window.BAG_DAY_ANALYTICS.event('reuse_give_click'));assert.equal((await s.events()).length,n);await other.evaluate(()=>window.BAG_DAY_ANALYTICS.setConsent(true));await s.ready();assert.equal((await s.events('page_view')).length,1);assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('blocked tag and missing config cannot break browsing or trigger false success events',async()=>{for(const missing of[false,true]){const s=await setup({tagBlocked:!missing});try{if(missing)await s.context.route('**/analytics_config.txt',r=>r.fulfill({status:404,body:'missing'}));await reuse(s);await s.page.waitForFunction(()=>['tag_unavailable','configuration_missing'].includes(window.BAG_DAY_ANALYTICS.status().state));await s.page.locator('#allLocalities').check();assert.equal((await s.events()).length,0);assert.deepEqual(s.errors,[])}finally{await s.close()}}});
test('sponsor exposure is visible, deduplicated across rerenders, and clicks retain sponsor/placement attribution',async()=>{const s=await setup();try{await home(s);await s.ready();const a=s.page.locator('.sponsor-link');await a.waitFor();await a.scrollIntoViewIfNeeded();await count(s,'sponsor_impression',1);const impression=(await s.events('sponsor_impression'))[0];assert.equal(impression.params.sponsor_id,'TEST-SPONSOR');assert.equal(impression.params.placement_locality,'Żejtun');assert.equal(impression.params.sponsor_slot,1);assert.equal(impression.params.advert_format,'text');await s.page.evaluate(()=>{for(let i=0;i<8;i++)window.BAG_DAY_SPONSORS.render('Żejtun',new Date())});await s.page.waitForTimeout(1300);assert.equal((await s.events('sponsor_impression')).length,1);for(let i=0;i<3;i++)await a.click();await count(s,'sponsor_click',3);await count(s,'sponsor_click_after_view',1);privateFree(await s.events());assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('exposure requires a continuous visible second and resets while inert, hidden or outside the viewport',async()=>{const s=await setup();try{await reuse(s);await s.ready();await s.page.evaluate(()=>{const e=document.createElement('div');e.id='measureFixture';e.style='position:fixed;top:0;left:0;width:120px;height:60px;background:white;z-index:100';document.body.append(e);window.BAG_DAY_ANALYTICS.observe(e,'sponsor_impression',{sponsor_id:'VISIBLE-TEST'},'visible-test')});await s.page.waitForTimeout(600);await s.page.locator('#measureFixture').evaluate(e=>e.inert=true);await s.page.waitForTimeout(400);await s.page.locator('#measureFixture').evaluate(e=>e.inert=false);await s.page.waitForTimeout(600);assert.equal((await s.events('sponsor_impression')).filter(e=>['VISIBLE-TEST','OFFSCREEN','IMAGE-TEST'].includes(e.params.sponsor_id)).length,0);await s.page.waitForFunction(()=>(window.__gaCommands||[]).some(c=>c[0]==='event'&&c[1]==='sponsor_impression'&&['VISIBLE-TEST','IMAGE-TEST'].includes(c[2].sponsor_id)));await s.page.evaluate(()=>{const e=document.querySelector('#measureFixture');e.style.top='-1000px';window.BAG_DAY_ANALYTICS.observe(e,'sponsor_impression',{sponsor_id:'OFFSCREEN'},'offscreen')});await s.page.waitForTimeout(1300);assert.equal((await s.events('sponsor_impression')).filter(e=>['VISIBLE-TEST','OFFSCREEN','IMAGE-TEST'].includes(e.params.sponsor_id)).length,1)}finally{await s.close()}});
test('banner exposure waits for actual image content instead of a blank loading rectangle',async()=>{const s=await setup();try{await reuse(s);await s.ready();await s.page.evaluate(()=>{const e=document.createElement('div');e.id='imageMeasure';e.style='position:fixed;top:0;left:0;width:120px;height:60px;background:white;z-index:100';e.append(new Image());document.body.append(e);window.BAG_DAY_ANALYTICS.observe(e,'sponsor_impression',{sponsor_id:'IMAGE-TEST'},'image-test')});await s.page.waitForTimeout(1300);assert.equal((await s.events('sponsor_impression')).filter(e=>['VISIBLE-TEST','OFFSCREEN','IMAGE-TEST'].includes(e.params.sponsor_id)).length,0);await s.page.locator('#imageMeasure img').evaluate(i=>{const c=document.createElement('canvas');c.width=1;c.height=1;c.getContext('2d').fillRect(0,0,1,1);i.src=c.toDataURL()});await s.page.waitForFunction(()=>(window.__gaCommands||[]).some(c=>c[0]==='event'&&c[1]==='sponsor_impression'&&['VISIBLE-TEST','IMAGE-TEST'].includes(c[2].sponsor_id)));assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('phone request, Google success, reveal, call-button intent and public advert click are separate and private',async()=>{const s=await setup();try{await reuse(s);await s.ready();await s.page.locator('#feed .item-row').first().click();await count(s,'reuse_item_open',1);await s.page.getByRole('button',{name:'View phone number'}).click();await count(s,'reuse_phone_request',1);assert.equal((await s.events('reuse_phone_revealed')).length,0);await s.page.getByRole('button',{name:'Continue with Google'}).click();await s.page.locator('a[href="tel:+35699123456"]').waitFor();await count(s,'reuse_signin_success',1);await count(s,'reuse_phone_revealed',1);await s.page.locator('a[href="tel:+35699123456"]').click();await count(s,'reuse_phone_call_click',1);await s.page.locator('#detailAdvert').click();await count(s,'reuse_advert_click',1);privateFree(await s.events());assert.deepEqual(s.errors,[])}finally{await s.close()}});
test('item attempts, errors, successful creation, edits and taken status use API outcomes and omit submitted content',async()=>{const s=await setup({signed:true});try{await reuse(s);await s.ready();await s.page.locator('#give').click();await s.page.locator('#listingTitle').fill('Free household item');await s.page.locator('#description').fill('PRIVATE_DESCRIPTION');await s.page.locator('#phone').fill('35699123456');await s.page.locator('#link').fill('https://example.test/PRIVATE_ADVERT');await s.page.locator('#free').check();s.setFail(true);await s.page.getByRole('button',{name:'Submit free item'}).click();await s.page.locator('#itemError:not([hidden])').waitFor();await count(s,'reuse_item_submit',1);await count(s,'reuse_action_error',1);assert.equal((await s.events('reuse_item_submitted')).length,0);s.setFail(false);await s.page.getByRole('button',{name:'Submit free item'}).click();await s.page.locator('#content .item-row').first().click();await s.page.getByRole('button',{name:'Edit',exact:true}).waitFor();await count(s,'reuse_item_submitted',1);assert.equal((await s.events('reuse_item_submitted'))[0].params.contact_type,'both');await s.page.getByRole('button',{name:'Edit',exact:true}).click();await s.page.locator('#free').check();await s.page.getByRole('button',{name:'Save changes'}).click();await s.page.locator('#content .item-row').first().click();await s.page.getByRole('button',{name:'Mark as taken'}).waitFor();await count(s,'reuse_item_edit_saved',1);await s.page.getByRole('button',{name:'Mark as taken'}).click();await count(s,'reuse_item_taken',1);privateFree(await s.events());assert.deepEqual(s.errors,[])}finally{await s.close()}});
