for(const [width,height] of [[320,640],[390,780],[844,390],[1280,900]])test('compact list, details and three sponsor banners fit '+width+'x'+height,async()=>{const s=await setup({width,height,signed:true,sponsorCount:3,sponsorImages:true,extraItems:25});try{await reuse(s);await s.page.locator('.sponsor-banner').last().waitFor();await s.page.waitForFunction(()=>[...document.querySelectorAll('.sponsor-banner')].every(i=>i.complete&&i.naturalWidth));assert.equal(await s.page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);const layout=await s.page.evaluate(()=>{const main=document.querySelector('#reuseScroll').getBoundingClientRect(),dock=document.querySelector('#sponsorDock').getBoundingClientRect();return{mainBottom:main.bottom,dockTop:dock.top,dockBottom:dock.bottom,viewport:innerHeight,scrolls:document.querySelector('#reuseScroll').scrollHeight>document.querySelector('#reuseScroll').clientHeight}});assert.ok(layout.mainBottom<=layout.dockTop+1);assert.ok(layout.dockBottom<=layout.viewport+1);assert.equal(layout.scrolls,true);const firstRow=await s.page.locator('#feed .item-row').first().boundingBox();assert.ok(firstRow.y+firstRow.height<=layout.dockTop+1,'first item must be visible on opening');if(process.env.QA_OUTPUT){mkdirSync(process.env.QA_OUTPUT,{recursive:true});await s.page.screenshot({path:path.join(process.env.QA_OUTPUT,'compact_'+width+'x'+height+'.png')})}await s.page.locator('#feed .item-row').first().click();await s.page.locator('#revealPhone').click();await s.page.locator('#callOwner').waitFor();const detail=await s.page.locator('#detailsDialog').boundingBox(),dock=await s.page.locator('#sponsorDock').boundingBox();assert.ok(detail.y+detail.height<=dock.y+1);assert.ok(detail.y>=0);assert.ok(Math.abs(detail.x+detail.width/2-width/2)<=2,'detail must be horizontally centered');assert.ok(Math.abs(detail.y+detail.height/2-height/2)<=2,'detail must be vertically centered');assert.equal(await s.page.locator('#detailsDialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);if(process.env.QA_OUTPUT)await s.page.screenshot({path:path.join(process.env.QA_OUTPUT,'detail_'+width+'x'+height+'.png')});await s.page.locator('#closeDetails').click();await s.page.locator('#give').click();await s.page.locator('#description').waitFor();assert.equal(await s.page.locator('#description').isVisible(),true);assert.equal(await s.page.locator('#itemDialog').evaluate(e=>e.scrollWidth>e.clientWidth),false);assert.deepEqual(s.errors,[])}finally{await s.close()}});

