function ownFixture(s){const own={...s.publicItems[0],title:'Toy train for kids',description:'A vintage wooden toy train.',item_emojis:'🎁🧸',status:'LIVE',revision:7,contact_phone:'+35699123456'};s.fixtureMe.items=[own];return own}
test('ownership: both tabs offer the same owner details and preserve full edit values',async()=>{
 const s=await setup({signed:true,width:390,height:780});try{
  const own=ownFixture(s);await reuse(s);
  // Refresh on public open must pick up a more recent authenticated revision.
  own.revision=8;
  await s.page.locator('#feed .item-row').first().click();
  await s.page.locator('#editDetail').waitFor();
  assert.equal(await s.page.locator('#takeDetail').isVisible(),true);
  assert.equal(await s.page.locator('#withdrawDetail').isVisible(),true);
  assert.equal(await s.page.locator('#callOwner').count(),0);assert.equal(await s.page.locator('#revealPhone').count(),0);assert.equal(await s.page.locator('.detail-contact').count(),0);
  assert.equal(s.requests.filter(r=>r.p==='/reuse/me').length,2);
  const publicDetail=await s.page.locator('#detailsDialog').innerText();
  await s.page.locator('#closeDetails').click();await s.page.locator('#mineTab').click();await s.page.locator('#addItem').waitFor();
  await s.page.locator('#content .item-row').click();await s.page.locator('#editDetail').waitFor();
  assert.equal(await s.page.locator('#detailsDialog').innerText(),publicDetail);
  await s.page.locator('#closeDetails').click();await s.page.locator('#browseTab').click();
  await s.page.locator('#feed .item-row').first().click();await s.page.locator('#editDetail').click();
  assert.equal(await s.page.locator('#listingTitle').inputValue(),own.title);
  assert.equal(await s.page.locator('#description').inputValue(),own.description);
  assert.equal(await s.page.locator('#phone').inputValue(),own.contact_phone);
  assert.equal(await s.page.locator('#link').inputValue(),own.external_url);
  assert.equal(await s.page.locator('#itemEmojis').inputValue(),own.item_emojis);
  await s.page.locator('#listingTitle').fill('Wooden toy train');await s.page.locator('#free').check();
  await s.page.getByRole('button',{name:'Save changes',exact:true}).click();
  await s.page.locator('#itemDialog').waitFor({state:'hidden'});
  const sent=s.requests.find(r=>r.method==='PATCH');assert.equal(sent.p,'/reuse/items/'+own.item_id);assert.equal(sent.body.revision,8);
  privateFree(await s.events());assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
