for(const action of ['untouched','replace','clear'])test('v18: editing old extra icons '+action,async()=>{
 const s=await setup({signed:true});try{
  const own=ownFixture(s);own.item_emojis='🚲🧺🔧';await reuse(s);await s.page.locator('#feed .item-row').first().click();await s.page.locator('#editDetail').click();assert.equal(await s.page.locator('#selectedEmojis').textContent(),'🚲');assert.equal(await s.page.locator('#itemEmojis').inputValue(),'🚲🧺🔧');
  if(action==='replace'){await editIcons(s);await s.page.locator('#manualIcons').click();await openManualIcons(s);await s.page.locator('#emojiSearch').fill('shoes');await s.page.getByRole('button',{name:'shoes',exact:true}).click()}else if(action==='clear'){await editIcons(s);await s.page.locator('#clearIcons').click();}
  await s.page.locator('#free').check();await s.page.getByRole('button',{name:'Save changes',exact:true}).click();await s.page.locator('#itemDialog').waitFor({state:'hidden'});assert.equal(s.requests.find(r=>r.method==='PATCH').body.item_emojis,action==='untouched'?'🚲🧺🔧':action==='replace'?'👟':'');assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});

test('v19: All Localities opens by default; unticking returns to GPS after a manual locality choice',async()=>{
 const s=await setup({width:390,height:780});try{
  await s.context.route('https://nominatim.openstreetmap.org/**',r=>r.fulfill({json:{address:{town:'Kalkara',country:'Malta'}}}));
  await reuse(s);assert.equal(await s.page.locator('#allLocalities').isChecked(),true);assert.equal(await s.page.locator('#localityChoice').isVisible(),false);await s.page.waitForFunction(()=>document.querySelector('#browseLocality').value==='K');await s.page.locator('#feed [data-item-id="two"]').waitFor();assert.equal(await s.page.locator('#feed .item-row').count(),2);
  await s.page.locator('#allLocalities').uncheck();assert.equal(await s.page.locator('#browseLocality').inputValue(),'K');await s.page.waitForFunction(()=>document.querySelectorAll('#feed .item-row').length===1&&document.querySelector('#feed .item-row').dataset.itemId==='two');
  await s.page.locator('#browseLocality').selectOption('Z');await s.page.locator('#allLocalities').check();await s.page.locator('#allLocalities').uncheck();assert.equal(await s.page.locator('#browseLocality').inputValue(),'K');assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
test('v19: delayed GPS keeps All selected and cannot overwrite a manual dropdown choice',async()=>{
 const s=await setup();let release;const gate=new Promise(r=>release=r);try{
  await s.context.route('https://nominatim.openstreetmap.org/**',async r=>{await gate;await r.fulfill({json:{address:{town:'Kalkara',country:'Malta'}}})});
  await reuse(s);await s.page.locator('#feed [data-item-id="two"]').waitFor();assert.equal(await s.page.locator('#allLocalities').isChecked(),true);
  await s.page.locator('#allLocalities').uncheck();await s.page.locator('#browseLocality').selectOption('Z');const response=s.page.waitForResponse('https://nominatim.openstreetmap.org/**');release();await(await response).finished();await s.page.waitForTimeout(100);assert.equal(await s.page.locator('#browseLocality').inputValue(),'Z');assert.equal(await s.page.locator('#allLocalities').isChecked(),false);assert.deepEqual(s.errors,[]);
 }finally{release?.();await s.close()}
});
test('v19: unavailable GPS keeps All usable and unticking uses saved locality',async()=>{
 const s=await setup();try{
  await s.page.addInitScript(()=>Object.defineProperty(navigator,'geolocation',{value:{getCurrentPosition:(_,fail)=>fail({code:1})}}));await reuse(s);await s.page.waitForFunction(()=>document.querySelector('#locationHint').textContent.includes('GPS unavailable'));assert.equal(await s.page.locator('#allLocalities').isChecked(),true);await s.page.locator('#allLocalities').uncheck();assert.equal(await s.page.locator('#browseLocality').inputValue(),'Z');assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
for(const response of [{json:{icons:[]}},{status:503,json:{error:{message:'Temporarily unavailable'}}}])test('v19: an unsuccessful Auto Find keeps an existing icon '+(response.status||200),async()=>{
 const s=await setup({signed:true});try{
  const own=ownFixture(s);own.item_emojis='🚲🧺🔧';own.submitted_at=new Date().toISOString();let calls=0;await s.context.route(u=>u.pathname==='/api/v1/reuse/icons/suggest',r=>{calls++;return r.fulfill(response)});await reuse(s);await s.page.locator('#feed .item-row').first().click();await s.page.locator('#editDetail').click();
  assert.equal(await s.page.locator('#iconEditor').isVisible(),false);assert.equal(await s.page.locator('#selectedEmojis').textContent(),'🚲');await editIcons(s);assert.equal(await s.page.locator('#itemEmojis').inputValue(),'🚲🧺🔧');await enabledAI(s);await s.page.locator('#quickIcons').click();await idleAI(s);assert.equal(calls,1);assert.equal(await s.page.locator('#itemEmojis').inputValue(),'🚲🧺🔧');assert.equal(await s.page.locator('#selectedEmojis').textContent(),'🚲');assert.equal(await s.page.locator('#iconEditor').isVisible(),true);await s.page.locator('#keepIcon').click();assert.equal(await s.page.locator('#iconEditor').isVisible(),false);assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
test('v19: Keep current protects the selected icon against an in-flight Auto Find',async()=>{
 const s=await setup({signed:true});let release,started;const gate=new Promise(r=>started=r);try{
  const own=ownFixture(s);own.item_emojis='🚲';own.submitted_at=new Date().toISOString();await s.context.route(u=>u.pathname==='/api/v1/reuse/icons/suggest',async r=>{started();await new Promise(ok=>release=ok);await r.fulfill({json:{icons:['🐟']}})});
  await reuse(s);await s.page.locator('#feed .item-row').first().click();await s.page.locator('#editDetail').click();await enabledAI(s);await s.page.locator('#quickIcons').click();await gate;await s.page.locator('#keepIcon').click();release();await idleAI(s);assert.equal(await s.page.locator('#itemEmojis').inputValue(),'🚲');assert.equal(await s.page.locator('#iconEditor').isVisible(),false);assert.deepEqual(s.errors,[]);
 }finally{release?.();await s.close()}
});
test('v19: signing into your own public item offers Edit without fetching your phone',async()=>{
 const s=await setup();try{
  ownFixture(s);await reuse(s);await s.page.locator('#feed .item-row').first().click();await s.page.locator('#revealPhone').click();await s.page.getByRole('button',{name:'Continue with Google'}).click();await s.page.locator('#editDetail').waitFor();assert.equal(await s.page.locator('.detail-contact').count(),0);assert.equal(await s.page.locator('#callOwner').count(),0);assert.equal(s.requests.filter(r=>r.p.endsWith('/contact')).length,0);assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
for(const width of [320,390,844])test('v19: compact approval labels align on the right in My Items at '+width+'px',async()=>{
 const s=await setup({signed:true,width,height:width===844?390:780});try{
  const base=ownFixture(s);s.fixtureMe.items=['PENDING','LIVE','REJECTED'].map((status,i)=>({...base,item_id:'owned-'+i,title:['Bike for a new home','Books to collect','Small wooden chair'][i],status,submitted_at:new Date(Date.now()-i*60000).toISOString()}));
  await reuse(s);await s.page.locator('#mineTab').click();await s.page.locator('#addItem').waitFor();await s.page.locator('#content .approval-label').first().waitFor();assert.deepEqual(await s.page.locator('#content .approval-label').allTextContents(),['Waiting For Approval','Approved','Rejected']);
  for(const row of await s.page.locator('#content .item-row').all()){
   assert.equal(await row.evaluate(el=>el.scrollWidth>el.clientWidth),false);const meta=await row.locator('.item-meta').boundingBox(),label=await row.locator('.approval-label').boundingBox();assert.ok(label.x+label.width>=meta.x+meta.width-2);assert.ok(label.width<=111);
  }
  if(process.env.QA_OUTPUT){mkdirSync(process.env.QA_OUTPUT,{recursive:true});await s.page.screenshot({path:path.join(process.env.QA_OUTPUT,'my_items_labels_'+width+'.png')})}
  await s.page.locator('#content .item-row').first().click();assert.equal(await s.page.locator('#editDetail').isVisible(),true);assert.equal(await s.page.locator('.detail-contact').count(),0);assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
for(const [width,height]of [[320,640],[390,780],[844,390]])test('v19: icon is immediately before title; Edit Icon keeps selection visible while searching '+width+'px',async()=>{
 const s=await setup({signed:true,width,height});try{
  let calls=0;await s.context.route(u=>u.pathname==='/api/v1/reuse/icons/suggest',r=>{calls++;return r.fulfill({json:{icons:['🚲']}})});await openAIForm(s);
  assert.equal(await s.page.locator('#manualIcons').textContent(),'Manual Select');assert.equal(await s.page.locator('#quickIcons').textContent(),'Auto Find');assert.match(await s.page.locator('.emoji-picker legend').textContent(),/Title icon/);await enabledAI(s);await s.page.locator('#quickIcons').click();await idleAI(s);
  const badge=await s.page.locator('#selectedEmojis').boundingBox(),title=await s.page.locator('#listingTitle').boundingBox();assert.ok(badge.x+badge.width<=title.x);assert.ok(Math.abs(badge.y+badge.height/2-title.y-title.height/2)<2);assert.equal(await s.page.locator('#iconEditor').isVisible(),false);assert.equal(await s.page.locator('#editIcon').isVisible(),true);
  if(process.env.QA_OUTPUT){await s.page.locator('#listingTitle').scrollIntoViewIfNeeded();await s.page.screenshot({path:path.join(process.env.QA_OUTPUT,'icon_compact_'+width+'.png')})}
  await openManualIcons(s);assert.equal(await s.page.locator('#selectedEmojis').textContent(),'🚲');assert.equal(await s.page.locator('#selectedEmojis').isVisible(),true);await s.page.locator('#emojiSearch').fill('shoes');assert.equal(await s.page.locator('#itemEmojis').inputValue(),'🚲');assert.equal(calls,1);
  if(process.env.QA_OUTPUT)await s.page.screenshot({path:path.join(process.env.QA_OUTPUT,'icon_edit_'+width+'.png')});await s.page.getByRole('button',{name:'shoes',exact:true}).click();assert.equal(await s.page.locator('#selectedEmojis').textContent(),'👟');assert.equal(await s.page.locator('#iconEditor').isVisible(),false);assert.equal(await s.page.locator('#listingTitle').inputValue(),'Toy fish for cats');assert.deepEqual(s.errors,[]);
 }finally{await s.close()}
});
